<?php
require __DIR__.'/../app/bootstrap.php';
$u=require_permission('updates.manage');
$checks=[];
$checks[]=['PHP Version',PHP_VERSION,version_compare(PHP_VERSION,'8.1.0','>=')];
foreach(['pdo_mysql','json','fileinfo','mbstring','curl'] as $ext)$checks[]=['Extension '.$ext,extension_loaded($ext)?'Loaded':'Missing',extension_loaded($ext)||in_array($ext,['mbstring','curl'],true)];
try{db()->query('SELECT 1');$checks[]=['Database','Connected',true];}catch(Throwable $e){$checks[]=['Database','Error: '.$e->getMessage(),false];}
try{$m=(int)db()->query("SELECT COUNT(*) FROM schema_migrations")->fetchColumn();$checks[]=['Migrations',$m.' recorded',true];}catch(Throwable $e){$checks[]=['Migrations','Unavailable',false];}
$log=__DIR__.'/../storage/logs/runtime-errors.log';$lines=[];if(is_file($log)){$all=@file($log,FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)?:[];$lines=array_slice($all,-40);}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Runtime Health — <?=e(setting('site_name','ShahkotPK'))?></title><style>body{font-family:system-ui;background:#f5f7f6;color:#16251e;margin:0}.wrap{max-width:1100px;margin:40px auto;padding:0 18px}.head,.card{background:#fff;border:1px solid #dbe4df;border-radius:22px;padding:24px;margin-bottom:18px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px}.check{padding:16px;border:1px solid #e1e8e4;border-radius:16px}.ok{color:#087443}.bad{color:#b42318}pre{white-space:pre-wrap;word-break:break-word;background:#101814;color:#d7efe2;border-radius:16px;padding:18px;max-height:460px;overflow:auto}a{color:#176b46}</style></head><body><main class="wrap"><section class="head"><a href="/admin/">← Admin</a><h1>Runtime Health & HTTP 500 Diagnostics</h1><p>v3.4.1 recovery guard status. Sensitive database credentials are never displayed here.</p></section><section class="card"><div class="grid"><?php foreach($checks as $c):?><div class="check"><small><?=e($c[0])?></small><h3 class="<?=$c[2]?'ok':'bad'?>"><?=e($c[1])?></h3></div><?php endforeach;?></div></section><section class="card"><h2>Recent runtime errors</h2><?php if($lines):?><pre><?=e(implode("\n",$lines))?></pre><?php else:?><p>No fatal runtime errors have been recorded since this hotfix was installed.</p><?php endif;?></section></main></body></html>
